test("band colors match Tk viewer exactly", () => {
  assert.deepEqual(BAND_COLUMN_HEADERS, ["LTE DL", "LTE UL", "NR DL", "NR UL", "FR1 DL", "FR2 DL", "FR1 UL", "FR2 UL"]);
  assert.equal(bandColor("B3"), bandColorFromCell("B3C + B7A", "LTE DL")); // B3A/B3C share B3's color
  assert.equal(bandColor("B42") === bandColor("n42"), false);
  assert.equal(PALETTE.length, 40);
  assert.equal(bandColor("B3"), PALETTE[md5IntMod("B3", 40)]);
});

test("PALETTE is element-identical to viewer.py (order + hex strings)", () => {
  assert.deepEqual(PALETTE, [
    "#B71C1C", "#D32F2F", "#C2185B", "#AD1457", "#880E4F",
    "#7B1FA2", "#9C27B0", "#6A1B9A", "#512DA8", "#4527A0",
    "#3949AB", "#303F9F", "#283593", "#1A237E", "#1565C0",
    "#0D47A1", "#0277BD", "#01579B", "#00838F", "#006064",
    "#00796B", "#00695C", "#004D40", "#2E7D32", "#1B5E20",
    "#33691E", "#827717", "#8D6E63", "#795548", "#6D4C41",
    "#5D4037", "#4E342E", "#5F6368", "#455A64", "#37474F",
    "#263238", "#BF360C", "#D84315", "#E64A19", "#8E24AA",
  ]);
});

test("columnBandPrefix ports _column_band_prefix (substring, case-sensitive)", () => {
  assert.equal(columnBandPrefix("LTE DL"), "B");
  assert.equal(columnBandPrefix("LTE UL"), "B");
  assert.equal(columnBandPrefix("NR DL"), "n");
  assert.equal(columnBandPrefix("FR1 DL"), "n");
  assert.equal(columnBandPrefix("FR2 UL"), "n");
  assert.equal(columnBandPrefix("X LTE Y"), "B");
  assert.equal(columnBandPrefix("lte dl"), "n");
  assert.equal(columnBandPrefix("MIMO DL"), "n");
  assert.equal(columnBandPrefix(""), "n");
});

test("bandSpans prefixed vs plain tokens (viewer.py:49-66 semantics)", () => {
  assert.deepEqual(bandSpans("42E + 7A", "LTE DL"),
    [{ start: 0, end: 3, canonical: "B42" }, { start: 6, end: 8, canonical: "B7" }]);
  assert.deepEqual(bandSpans("78A + 41C", "NR DL"),
    [{ start: 0, end: 3, canonical: "n78" }, { start: 6, end: 9, canonical: "n41" }]);
  // _BAND_RE keeps the prefix AS WRITTEN: B3A is B3 even in an NR column.
  assert.deepEqual(bandSpans("B3A", "NR DL"), [{ start: 0, end: 3, canonical: "B3" }]);
  assert.deepEqual(bandSpans("n78", "LTE DL"), [{ start: 0, end: 3, canonical: "n78" }]);
  assert.deepEqual(bandSpans("B42G", "FR1 DL"), [{ start: 0, end: 4, canonical: "B42" }]);
  // "999Z" matches the plain regex (digits + one trailing letter), per Python.
  assert.deepEqual(bandSpans("999Z", "LTE DL"), [{ start: 0, end: 4, canonical: "B999" }]);
  assert.deepEqual(bandSpans("999Z", "NR DL"), [{ start: 0, end: 4, canonical: "n999" }]);
  assert.deepEqual(bandSpans("2 + 4", "FR1 UL"),
    [{ start: 0, end: 1, canonical: "n2" }, { start: 4, end: 5, canonical: "n4" }]);
  assert.deepEqual(bandSpans("1A + 1A", "FR2 DL"),
    [{ start: 0, end: 2, canonical: "n1" }, { start: 5, end: 7, canonical: "n1" }]);
  assert.deepEqual(bandSpans("n41D + n28A", "NR DL"),
    [{ start: 0, end: 4, canonical: "n41" }, { start: 7, end: 11, canonical: "n28" }]);
  assert.deepEqual(bandSpans("1 + 2 + 3", "NR UL"),
    [{ start: 0, end: 1, canonical: "n1" }, { start: 4, end: 5, canonical: "n2" }, { start: 8, end: 9, canonical: "n3" }]);
  assert.deepEqual(bandSpans("B66A + B2NONE", "LTE DL"), [{ start: 0, end: 4, canonical: "B66" }]);
});

test("bandSpans skips non-matching tokens but still advances offsets", () => {
  assert.deepEqual(bandSpans("XX + B3", "LTE DL"), [{ start: 5, end: 7, canonical: "B3" }]);
  assert.deepEqual(bandSpans("B3 + ", "LTE DL"), [{ start: 0, end: 2, canonical: "B3" }]);
  assert.deepEqual(bandSpans("42E + XX + 7A", "LTE DL"),
    [{ start: 0, end: 3, canonical: "B42" }, { start: 11, end: 13, canonical: "B7" }]);
  assert.deepEqual(bandSpans("8-", "LTE DL"), []);
  assert.deepEqual(bandSpans("b3", "LTE DL"), []);
  assert.deepEqual(bandSpans("B3AB", "LTE DL"), []);
  assert.deepEqual(bandSpans(" 42E", "LTE DL"), []);
  assert.deepEqual(bandSpans("42e", "LTE DL"), []);
  assert.deepEqual(bandSpans("FR1DL", "FR1 DL"), []);
  assert.deepEqual(bandSpans("LTE DL", "LTE DL"), []);
  assert.deepEqual(bandSpans("", "LTE DL"), []);
});

test("bandSpans non-band columns return [] (exact header membership)", () => {
  for (const [cell, header] of [["B3", "MIMO DL"], ["256", "SCS"], ["2 + 4", "DL (QAM)"], ["42E", "lte dl"], ["42E", "LTE"]]) {
    assert.deepEqual(bandSpans(cell, header), []);
  }
});

test("bandSpans Python str-regex parity: $-newline and Unicode Nd digits", () => {
  // Python '$' also matches just before a single trailing newline, and str \d
  // is Unicode category Nd; spans are measured in code points like len().
  assert.deepEqual(bandSpans("B3\n", "LTE DL"), [{ start: 0, end: 3, canonical: "B3" }]);
  assert.deepEqual(bandSpans("B3A\n", "LTE DL"), [{ start: 0, end: 4, canonical: "B3" }]);
  assert.deepEqual(bandSpans("B٤٢", "LTE DL"), [{ start: 0, end: 3, canonical: "B٤٢" }]);
  assert.deepEqual(bandSpans("B٣ + 5A", "LTE UL"),
    [{ start: 0, end: 2, canonical: "B٣" }, { start: 5, end: 7, canonical: "B5" }]);
  assert.deepEqual(bandSpans("𝟎3 + B1", "NR DL"),
    [{ start: 0, end: 2, canonical: "n𝟎3" }, { start: 5, end: 7, canonical: "B1" }]);
});

test("bandColorFromCell uses the first band token, null when none", () => {
  assert.equal(bandColorFromCell("B3C + B7A", "LTE DL"), bandColor("B3"));
  assert.equal(bandColorFromCell("XX + 7A", "LTE DL"), bandColor("B7"));
  assert.equal(bandColorFromCell("n41D + n28A", "NR DL"), bandColor("n41"));
  assert.equal(bandColorFromCell("8-", "LTE DL"), null);
  assert.equal(bandColorFromCell("B3", "MIMO DL"), null);
  assert.equal(bandColorFromCell("", "LTE DL"), null);
});

test("md5IntMod is exact int(md5(s.encode()).hexdigest(), 16) % m (Python-verified)", () => {
  assert.equal(md5IntMod("B3", 40), 34); // md5("B3") = 0c4ecd7b59ebc5b9f47974cb9845fd02
  assert.equal(md5IntMod("", 40), 6);
  assert.equal(md5IntMod("n78", 1024), 498);
  assert.equal(md5IntMod("BΩ", 40), 20); // utf-8 encoded like Python .encode()
  assert.equal(md5IntMod("𝟎3", 7), 4);
  assert.equal(md5IntMod("B3", 1), 0);
});

test("differential: 305 canonical colors match the Python viewer exactly", () => {
  assert.equal(GOLDEN.length, 305);
  const paletteSet = new Set(PALETTE);
  for (const [canonical, color] of GOLDEN) {
    assert.equal(bandColor(canonical), color, `bandColor(${JSON.stringify(canonical)})`);
    assert.ok(paletteSet.has(color), `${color} not in PALETTE`);
  }
});

test("bandSegments token-level helper for an HTML-table renderer", () => {
  assert.deepEqual(bandSegments("42E + XX + 7A", "LTE DL"), [
    { text: "42E", canonical: "B42" },
    { text: "XX", canonical: null },
    { text: "7A", canonical: "B7" },
  ]);
  assert.deepEqual(bandSegments("B3A", "NR DL"), [{ text: "B3A", canonical: "B3" }]);
  // Segments mirror cell.split(" + ") 1:1 (unparsable tokens keep canonical
  // null), so join(" + ") always reassembles the cell — including empty cells.
  assert.deepEqual(bandSegments("", "LTE DL"), [{ text: "", canonical: null }]);
  assert.deepEqual(bandSegments("B3", "MIMO DL"), []);
  for (const [cell, header] of [["42E + XX + 7A", "LTE DL"], ["B3C + B7A", "LTE DL"], ["8-", "LTE DL"]]) {
    assert.equal(bandSegments(cell, header).map((s) => s.text).join(" + "), cell);
  }
});

test("bandColor rejects non-string canonicals like Python (AttributeError)", () => {
  for (const bad of [null, undefined, 42, {}]) {
    assert.throws(() => bandColor(bad), TypeError);
  }
});

// --- static per-band-number colors (BAND_NUMBER_COLORS / bandColorClass) ------------

test("BAND_NUMBER_COLORS spot values match the Kotlin BAND_COLORS map", () => {
  assert.equal(BAND_NUMBER_COLORS.get(1), "#EE8700");
  assert.equal(BAND_NUMBER_COLORS.get(3), "#81A83D");
  assert.equal(BAND_NUMBER_COLORS.get(42), "#85E729");
  assert.equal(BAND_NUMBER_COLORS.get(78), "#DD0000");
  assert.equal(BAND_NUMBER_COLORS.get(110), "#BFD7C6");
  assert.equal(BAND_NUMBER_COLORS.get(127), "#7FFA86");
  assert.equal(BAND_NUMBER_COLORS.get(257), "#FF8B66");
  assert.equal(BAND_NUMBER_COLORS.get(263), "#9FAE7B");
  // The source map genuinely repeats 257's color for 258.
  assert.equal(BAND_NUMBER_COLORS.get(258), BAND_NUMBER_COLORS.get(257));
  // Coverage: 1..110, 125..127, 250..263 — 127 entries.
  assert.equal(BAND_NUMBER_COLORS.size, 127);
  for (const [num] of BAND_NUMBER_COLORS) {
    assert.match(BAND_NUMBER_COLORS.get(num), /^#[0-9A-F]{6}$/);
  }
});

test("bandNumberOf extracts the band number from a canonical", () => {
  assert.equal(bandNumberOf("B3"), 3);
  assert.equal(bandNumberOf("n78"), 78);
  assert.equal(bandNumberOf("n257"), 257);
  assert.equal(bandNumberOf("B42"), 42);
  // Canonicals never carry a class letter; anything unparsable is null.
  assert.equal(bandNumberOf("B3A"), null);
  assert.equal(bandNumberOf(""), null);
  assert.equal(bandNumberOf("x9"), null);
});

test("bandColorClass: same band number -> same class, LTE or NR alike", () => {
  assert.equal(bandColorClass("B3"), "band-n3");
  assert.equal(bandColorClass("n3"), "band-n3");
  assert.equal(bandColorClass("B78"), "band-n78");
  assert.equal(bandColorClass("n78"), "band-n78");
  assert.equal(bandColorClass("n257"), "band-n257");
});

test("bandColorClass falls back to the md5 palette for uncovered numbers", () => {
  // Covered ranges are 1..110, 125..127, 250..263 — everything else falls back.
  for (const canonical of ["n111", "n124", "B150", "n264", "n999"]) {
    assert.equal(bandColorClass(canonical), `band-c${bandColorIndex(canonical)}`);
  }
  // Non-ASCII digits never parse as a number -> md5 fallback too.
  assert.equal(bandColorClass("B١٢٣"), `band-c${bandColorIndex("B١٢٣")}`);
});
